        if (input.length() < 3) {
            return "No";
        }

        Set<String> set = new HashSet<>();
        set.add("ABC");
        set.add("ACB");
        set.add("BAC");
        set.add("BCA");
        set.add("CAB");
        set.add("CBA");

        for (int i = 0; i <= input.length() - 3; i++) {
            String k = input.substring(i, i + 3);
            if (set.contains(k)) {
                return "Yes";
            }
        }

        return "No";
    }
}

